import test from 'node:test';import assert from 'node:assert/strict';import React,{act} from 'react';import {createServer} from 'vite';import {fileURLToPath} from 'node:url';import {JSDOM} from 'jsdom';
async function ui(run){const vite=await createServer({configFile:false,root:fileURLToPath(new URL('../',import.meta.url)),server:{middlewareMode:true,watch:null},appType:'custom'}),dom=new JSDOM('<div id="root"></div>',{url:'http://localhost/'}),names=['window','document','HTMLElement','IS_REACT_ACT_ENVIRONMENT'],saved=new Map(names.map(k=>[k,Object.getOwnPropertyDescriptor(globalThis,k)]));let root;
 try{Object.assign(globalThis,{window:dom.window,document:dom.window.document,HTMLElement:dom.window.HTMLElement,IS_REACT_ACT_ENVIRONMENT:true});dom.window.HTMLDialogElement.prototype.showModal=function(){this.open=true;};dom.window.HTMLDialogElement.prototype.close=function(){this.open=false;};const {createRoot}=await import('react-dom/client'),forms=await vite.ssrLoadModule('/src/integrated/PaperForms.jsx');root=createRoot(document.getElementById('root'));const id=crypto.randomUUID(),book={version:1,createdAt:id,prices:{'AAPL.US':100},positions:[],params:{cashFloorPct:20,issuerCapPct:12,themeCapPct:25,feeBps:10,slippageBps:5,fx:{CNY:7.1,HKD:7.8}}},topic={id,createdAt:id,version:1,title:'虚构表单研究',hypothesis:{holdingHorizon:'一年',invalidation:'虚构反证'}};const props={book,topic,symbol:'AAPL.US',side:'buy',busy:false,onClose(){},mutate:async()=>null};const render=(kind,more={})=>act(()=>root.render(kind?React.createElement(forms[kind],{...props,...more}):null)),field=label=>[...document.querySelectorAll('label')].find(e=>e.firstChild?.textContent===label)?.querySelector('input,textarea,select'),fill=(label,value)=>act(()=>{const e=field(label);assert.ok(e,label);const proto=e.tagName==='TEXTAREA'?window.HTMLTextAreaElement.prototype:e.tagName==='SELECT'?window.HTMLSelectElement.prototype:window.HTMLInputElement.prototype;Object.getOwnPropertyDescriptor(proto,'value').set.call(e,value);e.dispatchEvent(new window.Event(e.tagName==='SELECT'?'change':'input',{bubbles:true}));}),submit=()=>document.querySelector('form').dispatchEvent(new window.Event('submit',{bubbles:true,cancelable:true}));await run({props,render,field,fill,submit,text:()=>document.body.textContent});}finally{if(root)await act(()=>root.unmount());for(const [k,d] of saved)if(d)Object.defineProperty(globalThis,k,d);else delete globalThis[k];dom.window.close();await vite.close();}}
test('paper proposal retains its note and frozen research/book versions through close and reopen',()=>ui(async({props,render,field,fill,text})=>{await render('Proposal');await fill('本次申请依据','虚构：保留未提交依据');await render(null);await render('Proposal',{book:{...props.book,version:2},topic:{...props.topic,version:2}});assert.equal(field('本次申请依据').value,'虚构：保留未提交依据');assert.match(text(),/冻结研究 v1/);assert.equal([...document.querySelectorAll('button')].find(b=>b.textContent==='提交模拟申请').disabled,true);}));
test('a late paper proposal receipt does not close the next dialog',()=>ui(async({props,render,fill,submit})=>{let resolve,closed=0;await render('Proposal',{mutate:()=>new Promise(r=>resolve=r),onClose:()=>closed++});await fill('本次申请依据','虚构旧请求');await act(()=>submit());await render(null);await render('Parameters');await act(async()=>resolve({paper:{...props.book,version:2}}));assert.equal(closed,0);assert.match(document.querySelector('h2').textContent,/组合演练参数/);}));
test('paper parameter form excludes synchronous repeated submits before parent busy renders',()=>ui(async({props,render,submit})=>{const replies=[];await render('Parameters',{mutate:()=>new Promise(r=>replies.push(r))});try{await act(()=>{submit();submit();});assert.equal(replies.length,1);}finally{await act(async()=>replies.forEach(r=>r({paper:{...props.book,version:2}})));}}));
test('approval note restores but confirmation does not, and a new book version requires explicit reset',()=>ui(async({props,render,fill,field})=>{const order={id:props.topic.id,createdAt:'same-order',status:'pending',symbol:'AAPL.US',side:'buy',qty:5,topicVersion:1,errors:[],estimate:{total:500,execution:100,currency:'USD',fee:1,fx:1},reason:'虚构申请',holdingHorizon:'一年',invalidation:'虚构反证'};await render('Decision',{order});await fill('决策备注','虚构待核对备注');await act(()=>document.querySelector('input[type="checkbox"]').click());assert.equal(document.querySelector('input[type="checkbox"]').checked,true);await render(null);await render('Decision',{order,book:{...props.book,version:2}});assert.equal(field('决策备注').value,'虚构待核对备注');assert.equal(document.querySelector('input[type="checkbox"]').checked,false);const approve=[...document.querySelectorAll('button')].find(b=>b.textContent==='批准模拟买入');assert.equal(approve.disabled,true);await act(()=>[...document.querySelectorAll('button')].find(b=>b.textContent==='丢弃审批备注并重新核对').click());assert.equal(field('决策备注').value,'');assert.equal(approve.disabled,true);}));
test('later parameter input survives a save receipt and remains based on the submitted book',()=>ui(async({props,render,fill,field,submit,text})=>{let resolve,closed=0;await render('Parameters',{mutate:()=>new Promise(r=>resolve=r),onClose:()=>closed++});await fill('最低现金比例 %','21');await act(()=>submit());await fill('最低现金比例 %','22');await act(async()=>resolve({paper:{...props.book,version:2}}));assert.equal(closed,0);assert.equal(field('最低现金比例 %').value,'22');await render('Parameters',{book:{...props.book,version:2}});assert.match(text(),/草稿基于 v1/);assert.equal([...document.querySelectorAll('button')].find(b=>b.textContent==='保存参数版本').disabled,true);}));
test('a late invalidated position review does not open a sell proposal after its dialog closes',()=>ui(async({props,render,fill,submit})=>{let resolve,exits=0,closed=0;const position={symbol:'AAPL.US',lifecycleId:props.topic.id,currentResearchVersion:1,researchVersion:1};await render('Review',{position,mutate:()=>new Promise(r=>resolve=r),onClose:()=>closed++,onExit:()=>exits++});await fill('结论','invalidated');await fill('新增事实、来源与对原逻辑的影响','虚构反证');await act(()=>submit());await render(null);await render('Parameters');await act(async()=>resolve({paper:{...props.book,version:2}}));assert.equal(exits,0);assert.equal(closed,0);assert.match(document.querySelector('h2').textContent,/组合演练参数/);}));
test('position review drafts are isolated by lifecycle; missing order/position never crashes the dialog',()=>ui(async({props,render,fill,field,text})=>{const position={symbol:'AAPL.US',lifecycleId:props.topic.id,currentResearchVersion:1,researchVersion:1};await render('Review',{position});await fill('新增事实、来源与对原逻辑的影响','只属于第一笔持仓');await render('Review',{position:{...position,lifecycleId:props.topic.id+'-second'}});assert.equal(field('新增事实、来源与对原逻辑的影响').value,'');await render('Review',{position});assert.equal(field('新增事实、来源与对原逻辑的影响').value,'只属于第一笔持仓');await render('Review',{position:undefined});assert.match(text(),/持仓已不在当前账本/);await render('Decision',{order:undefined});assert.match(text(),/申请已不在当前账本/);}));
